(6160915, 908556, 40391, '<td valign="top">I like the contrasting effect of the building against the lovely blues and whites of the sky.  The desat feel in the reflection works for me too.</td>', 'I like the contrasting effect of the building against the lovely blues and whites of the sky.  The desat feel in the reflection works for me too.', '2010-09-13 16:55:52.000000', NULL, 1),
(6160916, 908618, 117831, '<td valign="top">top 5! excellent job!</td>', 'top 5! excellent job!', '2010-09-13 16:56:15.000000', NULL, 1),
