(6163116, 908854, 96751, '<td valign="top">Stunning.  Incredibly well processed.  I just love gray with gold.</td>', 'Stunning.  Incredibly well processed.  I just love gray with gold.', '2010-09-15 16:10:25.000000', NULL, 1),
(6163120, 909237, 96751, '<td valign="top">This most certainly has the WOW factor!!!  An exceptional image in content, clarity, color, and impact.  I''m guessing HDR but superbly done.  And of course, the lightning is tremendous.  My one gripe is that this is more of a cityscape than a skyscape.  Were it not for that, I''d say this would ribbon - which it probably will anyway.</td>', 'This most certainly has the WOW factor!!!  An exceptional image in content, clarity, color, and impact.  I''m guessing HDR but superbly done.  And of course, the lightning is tremendous.  My one gripe is that this is more of a cityscape than a skyscape.  Were it not for that, I''d say this would ribbon - which it probably will anyway.', '2010-09-15 16:13:18.000000', NULL, 1),
(6163121, 908879, 96751, '<td valign="top">Magnificent.  Incredible detail. Superbly processed.  Not terribly crazy about the border...</td>', 'Magnificent.  Incredible detail. Superbly processed.  Not terribly crazy about the border...', '2010-09-15 16:15:05.000000', NULL, 1),
