(6163123, 908691, 96751, '<td valign="top">Incredible colors, but I find the crane rather distracting.</td>', 'Incredible colors, but I find the crane rather distracting.', '2010-09-15 16:16:31.000000', NULL, 1),
(6163126, 909197, 96751, '<td valign="top">Nice sense of movement.  There is an odd, green area in the center of the image, making the sky an uneven color.</td>', 'Nice sense of movement.  There is an odd, green area in the center of the image, making the sky an uneven color.', '2010-09-15 16:17:25.000000', NULL, 1),
(6163127, 909069, 96751, '<td valign="top">This image seems tilted to me.  Since the beams are meant to be vertical, I think it is a significant flaw.Exceptional clarity and detail though.</td>', 'This image seems tilted to me.  Since the beams are meant to be vertical, I think it is a significant flaw.Exceptional clarity and detail though.', '2010-09-15 16:18:33.000000', NULL, 1),
(6163128, 908125, 96751, '<td valign="top">I simply adore this image, in spite of it not really being about the sky.  The subject here is decidedly the plant.  But it is stunning, and a fave.</td>', 'I simply adore this image, in spite of it not really being about the sky.  The subject here is decidedly the plant.  But it is stunning, and a fave.', '2010-09-15 16:19:41.000000', NULL, 1),
(6163129, 909294, 96751, '<td valign="top">Great composition, although the extreme contrast renders the bales almost invisible.  I might have dodged them a bit.</td>', 'Great composition, although the extreme contrast renders the bales almost invisible.  I might have dodged them a bit.', '2010-09-15 16:20:24.000000', NULL, 1),
(6163130, 909199, 96751, '<td valign="top">I love the rays and the upper portion of the sky on this.  The rest is too HDR for my taste.</td>', 'I love the rays and the upper portion of the sky on this.  The rest is too HDR for my taste.', '2010-09-15 16:21:17.000000', NULL, 1),
(6163131, 909056, 96751, '<td valign="top">Incredibly well done, although I might have played with curves or color balance to remove some of the redness from the sky.</td>', 'Incredibly well done, although I might have played with curves or color balance to remove some of the redness from the sky.', '2010-09-15 16:22:11.000000', NULL, 1),
