(6165268, 908854, 114225, '<td valign="top">Excellent timing. I just attempted a similar shot while on holiday, and had a terrible time capturing what I saw.</td>', 'Excellent timing. I just attempted a similar shot while on holiday, and had a terrible time capturing what I saw.', '2010-09-18 09:43:17.000000', NULL, 1),
(6165270, 909268, 114225, '<td valign="top">Good job with the expansive feeling to the sky. Looks like there is a fairly high amount of noise in the photo, maybe taken with a high ISO?</td>', 'Good job with the expansive feeling to the sky. Looks like there is a fairly high amount of noise in the photo, maybe taken with a high ISO?', '2010-09-18 09:46:34.000000', NULL, 1),
(6165272, 908873, 114225, '<td valign="top">Interesting entry. I have thought about taking shots of jet trails, but they never seem that interesting in the photo.</td>', 'Interesting entry. I have thought about taking shots of jet trails, but they never seem that interesting in the photo.', '2010-09-18 09:47:59.000000', NULL, 1),
(6165273, 909223, 114225, '<td valign="top">This area has a lot of potential for a great photo, I just don''t think this photo captured that full potential. Maybe it you could have waited until a sailboat was closer, and if you included less water it would have worked a bit better.</td>', 'This area has a lot of potential for a great photo, I just don''t think this photo captured that full potential. Maybe it you could have waited until a sailboat was closer, and if you included less water it would have worked a bit better.', '2010-09-18 09:49:56.000000', NULL, 1),
(6165275, 909153, 114225, '<td valign="top">Interesting sky, but I don''t think this photo fits with the spirit of the challenge. My eyes were instantly drawn to the main windmill, which makes it the subject of the photo instead of the sky.</td>', 'Interesting sky, but I don''t think this photo fits with the spirit of the challenge. My eyes were instantly drawn to the main windmill, which makes it the subject of the photo instead of the sky.', '2010-09-18 09:50:50.000000', NULL, 1),
