(6166621, 909268, 98339, '<td valign="top">to me this is very very grainy...</td>', 'to me this is very very grainy...', '2010-09-20 00:45:19.000000', NULL, 1),
(6166622, 909237, 98339, '<td valign="top">for me like your title...this is more cityscape than sky...you have captured a moment in time...</td>', 'for me like your title...this is more cityscape than sky...you have captured a moment in time...', '2010-09-20 00:45:54.000000', NULL, 1),
