(6166741, 909160, 59267, '<td valign="top">The shape of your clouds and the colors are so beautiful! congratulations on your ribbon!</td>', 'The shape of your clouds and the colors are so beautiful! congratulations on your ribbon!', '2010-09-20 01:33:22.000000', NULL, 0),
